// Generates public/media/day-NN/narration.mp3 and continuation.mp3 with ElevenLabs,
// from the same texts the app shows (content/texts.md).
//
//   npm run tts                     all missing or changed files
//   npm run tts -- --dry-run        only list what would be generated and the character count
//   npm run tts -- --day 3          one day (also: --day 3-7)
//   npm run tts -- --only narration narration or continuation only
//   npm run tts -- --force          also overwrite files that were not generated by this script
//
// Needs ELEVENLABS_API_KEY and ELEVENLABS_VOICE_ID in .env (optional: ELEVENLABS_MODEL).
// Model, seed and voice settings: content/tts-settings.json.
// content/audio-manifest.json remembers a hash of the text and voice behind each file, so
// re-running only regenerates what changed in texts.md.
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { parseTexts } from './parse-texts.mjs';

const args = process.argv.slice(2);
const flag = (name) => args.includes(`--${name}`);
const opt = (name) => { const i = args.indexOf(`--${name}`); return i >= 0 ? args[i + 1] : undefined; };

const dryRun = flag('dry-run');
const force = flag('force');
const only = opt('only');
if (only && !['narration', 'continuation'].includes(only)) throw new Error('--only must be narration or continuation');
const [from, to] = (opt('day') ?? '1-24').split('-').map(Number);
const dayRange = [from, to ?? from];

const API_KEY = process.env.ELEVENLABS_API_KEY;
const VOICE = process.env.ELEVENLABS_VOICE_ID;
// Model, seed and voice settings live in content/tts-settings.json. Changing any of them
// regenerates all files on the next run.
const settings = JSON.parse(readFileSync(new URL('../content/tts-settings.json', import.meta.url), 'utf8'));
const MODEL = process.env.ELEVENLABS_MODEL || settings.model;
const FORMAT = settings.outputFormat;
const SEED = settings.seed;
const VOICE_SETTINGS = settings.voiceSettings;

if (!dryRun && (!API_KEY || !VOICE)) {
  console.error('Set ELEVENLABS_API_KEY and ELEVENLABS_VOICE_ID in .env (see README, "Audio with ElevenLabs").');
  process.exit(1);
}

const manifestUrl = new URL('../content/audio-manifest.json', import.meta.url);
const manifest = existsSync(manifestUrl) ? JSON.parse(readFileSync(manifestUrl, 'utf8')) : {};
const saveManifest = () => writeFileSync(manifestUrl, JSON.stringify(manifest, null, 2) + '\n');

const days = parseTexts();
const jobs = [];
for (let num = dayRange[0]; num <= dayRange[1]; num++) {
  const d = days[num];
  if (!d) throw new Error(`Day ${num} missing in texts.md`);
  for (const kind of ['narration', 'continuation']) {
    if (only && kind !== only) continue;
    // Paragraph breaks become pauses in the reading.
    const text = d[kind].join('\n\n');
    if (!text) { console.warn(`Day ${num}: no ${kind} text, skipped`); continue; }
    const key = `day-${String(num).padStart(2, '0')}/${kind}`;
    const file = new URL(`../public/media/${key}.mp3`, import.meta.url);
    const hash = createHash('sha256').update(JSON.stringify([text, VOICE, MODEL, VOICE_SETTINGS, SEED, FORMAT])).digest('hex').slice(0, 16);
    const entry = manifest[key];
    if (existsSync(file)) {
      if (entry?.hash === hash) continue; // up to date
      if (!entry && !force) { console.log(`${key}.mp3 exists and was not generated here, kept (use --force to replace)`); continue; }
    }
    jobs.push({ key, file, text, hash });
  }
}

const chars = jobs.reduce((s, j) => s + j.text.length, 0);
console.log(`Model ${MODEL}, seed ${SEED}, voice settings ${JSON.stringify(VOICE_SETTINGS)}`);
console.log(`${jobs.length} file(s), ${chars.toLocaleString('en')} characters`);
if (dryRun) { for (const j of jobs) console.log(`  ${j.key}.mp3  (${j.text.length} chars)`); process.exit(0); }

async function synthesize(text) {
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${VOICE}?output_format=${FORMAT}`, {
      method: 'POST',
      headers: { 'xi-api-key': API_KEY, 'Content-Type': 'application/json', Accept: 'audio/mpeg' },
      body: JSON.stringify({ text, model_id: MODEL, voice_settings: VOICE_SETTINGS, seed: SEED }),
    });
    if (res.ok) return Buffer.from(await res.arrayBuffer());
    const body = await res.text();
    if ((res.status === 429 || res.status >= 500) && attempt < 4) {
      const wait = 2 ** attempt * 1000;
      console.warn(`  ${res.status}, retrying in ${wait / 1000}s`);
      await new Promise((r) => setTimeout(r, wait));
      continue;
    }
    throw new Error(`ElevenLabs ${res.status}: ${body}`);
  }
}

for (const j of jobs) {
  process.stdout.write(`${j.key}.mp3 … `);
  const audio = await synthesize(j.text);
  mkdirSync(new URL('.', j.file), { recursive: true });
  const tmp = new URL(`${j.file.href}.tmp`);
  writeFileSync(tmp, audio);
  renameSync(tmp, j.file);
  manifest[j.key] = { hash: j.hash, voice: VOICE, model: MODEL, seed: SEED, voiceSettings: VOICE_SETTINGS, chars: j.text.length, generated: new Date().toISOString() };
  saveManifest(); // after every file, so an interrupted run resumes where it stopped
  console.log(`${(audio.length / 1024).toFixed(0)} KB`);
}
console.log('Done.');
